const records = [];
function add(r) {
  const places = (r.places ?? [r.from, r.to]).map(name => typeof name !== 'string' ? name : typeof P[name] === 'object' ? { name, ...P[name] } : { name, query: P[name] ?? name });
  records.push({
    id: r.id, river: r.river, from: r.from, to: r.to,
    region: r.region ?? 'Kaszuby', province: r.province ?? 'pomorskie',
    areas: ['pomorze', ...(r.bory ? ['bory-tucholskie'] : [])],
    lengthKm: r.km, lengthNote: r.lengthNote ?? `${r.km.toLocaleString('pl-PL')} km według wskazanego źródła; kilometraż dotyczy tego wariantu.`,
    difficulty: r.level, sourceDifficulty: r.grade, type: r.type ?? 'river', obstacles: r.logs,
    character: r.character, description: r.description,
    current: r.current ?? 'Źródło nie podaje prędkości nurtu; jego charakter opisano powyżej.',
    obstacleNote: r.hazards, portages: r.portages, supNote: r.sup ?? sup[r.level],
    source: r.source, ...(r.sources ? { additionalSources: r.sources } : {}), accessedAt: '2026-10-22',
    ...(r.duration ? { sourceDuration: r.duration } : {}), ...(r.tripKind ? { tripKind: r.tripKind } : {}),
    ...(r.accessNote ? { accessNote: r.accessNote } : {}),
    map: { rivers: r.rivers ?? r.river.split(' + ').map(name => `${name} rzeka, pomorskie`), places, bounds: [16.2, 53.25, 19, 54.9], ...(r.schematic ? { schematic: true } : {}), ...(r.mapNote ? { note: r.mapNote } : {}) }
  });
}

