add({ id: 'radunia-stezyca-gdansk', river: 'Radunia', from: 'Stężyca', to: 'Gdańsk', km: 97, grade: 'Łatwy w ofercie wielodniowej', level: 'moderate', logs: 'some', type: 'mixed', source: multi('radunia__kwintesencja_szwajcarii_kaszubskiej'), region: 'Kaszuby / okolice Gdańska', duration: '6 dni kajakiem', tripKind: 'multi', character: 'Jeziora i elektrownie z transportem', description: 'Plan wielodniowy łączący jeziora kaszubskie z dolną Radunią. Odcinek Jar Raduni jest pomijany transportem lądowym.', hazards: 'Otwarte jeziora, progi i liczne budowle wodne; opis wymaga organizacji przewozu.', portages: '12 według oferty oraz przewózka omijająca Jar Raduni.', accessNote: 'Jar Raduni jest wyłączony ze spływów. To plan z transportem, a nie ciągły ślad wodny do Gdańska.', schematic: true, places: ['Stężyca', 'Chmielno', 'Ostrzyce', 'Żukowo', 'Straszyn', 'Pruszcz Gdański', 'Gdańsk'] });
add({ id: 'brda-nowa-brda-gostycyn', river: 'Brda', rivers: ['Brda'], from: 'Nowa Brda', to: 'Gostycyn-Nogawica', km: 140, grade: 'Łatwy w karcie oferty', level: 'advanced', logs: 'some', type: 'mixed', source: multi('brda_absolutna_klasyka'), sources: [ps('brda-woziwoda-pila_mlyn')], region: 'Kaszuby / Bory Tucholskie', bory: true, province: 'pomorskie / kujawsko-pomorskie', duration: '6 dni kajakiem', tripKind: 'multi', character: 'Wielodniowa klasyka Brdy', description: 'Długa wyprawa przez jeziora i leśne odcinki Brdy. Całość obejmuje również trudniejsze fragmenty w rejonie Piekiełka.', hazards: 'Pnie, kamienie i bystrza na trudniejszych etapach, fale na jeziorach.', portages: '7 według karty oferty.', sup: 'Ocena zaawansowana na SUP uwzględnia długość całej wyprawy i Piekiełko, mimo łatwej ogólnej oceny kajakowej operatora.' });
add({ id: 'leba-sianowo-gac', river: 'Łeba', from: 'Sianowo', to: 'Gać', km: 102, grade: 'Trudny', level: 'advanced', logs: 'many', source: multi('leba_czyli_roznie_bywa_ale_final_jest_niezwykly'), region: 'Kaszuby / dolina Łeby', duration: '6 dni kajakiem', tripKind: 'multi', character: 'Od przełomów do nadmorskiej równiny', description: 'Górna Łeba z wąskim korytem i szybszym nurtem, dalej rozległa dolina i okolice jeziora Łebsko. Odcinek kończy się w Gaci.', hazards: 'Płycizny, korzenie, kamienie i przeszkody górnego biegu.', portages: '14 według karty oferty.', accessNote: 'Ta trasa kończy się przed jeziorem Łebsko. Opis nie oznacza udostępnienia jeziora ani rezerwatu do swobodnego pływania.' });
add({ id: 'bytowa-bytow-ustka', river: 'Bytowa + Słupia', from: 'Bytów', to: 'Ustka', km: 105, grade: 'Średni', level: 'advanced', logs: 'many', type: 'mixed', source: multi('bytowa_kaszubska_amazonka_'), duration: '5 dni kajakiem', tripKind: 'multi', character: 'Bystrza Bytowy, dolina Słupi', description: 'Od Bytowa przez Zalew Bytowy i Jezioro Głębokie, dalej systemem Słupi do Ustki. Trasa łączy techniczny dopływ z długą wyprawą.', hazards: 'Progi, pnie, bystrza i budowle wodne.', portages: '4 według oferty; przy Jeziorze Głębokim kontynuacja wymaga przewózki.', accessNote: 'Przewózka Jezioro Głębokie–Gałąźnia Mała; kanał elektrowni nie jest szlakiem spływu.', schematic: true, places: ['Bytów', 'Jezioro Głębokie (Słupia)', 'Gałąźnia Mała', 'Słupsk', 'Ustka'] });
add({ id: 'skotawa-jawory-ustka', river: 'Skotawa + Słupia', from: 'Jawory', to: 'Ustka', km: 86, grade: 'Trudny', level: 'advanced', logs: 'many', source: multi('skotawa_czyli_zmienny_nurt'), duration: '5 dni kajakiem', tripKind: 'multi', character: 'Zwałkowym dopływem do morza', description: 'Od łąkowej Skotawy przez dzikie lasy i Dębnicę Kaszubską na Słupię. Dalszy etap prowadzi przez Słupsk do Ustki.', hazards: 'Liczne zatopione drzewa i bystrza, szczególnie na dolnej Skotawie.', portages: '5 według oferty; długa przenoska w Dębnicy i elektrownia Skarszów Dolny.', places: ['Jawory', 'Dębnica Kaszubska', 'Słupsk', 'Ustka'] });
add({ id: 'wda-lipusz-tlen', river: 'Wda', rivers: ['Wda'], from: 'Lipusz', to: 'Tleń', km: 138, grade: 'Łatwy w karcie oferty', level: 'advanced', logs: 'some', type: 'mixed', source: multi('klasyczna_wda_'), sources: [hydro, hydroGuide], region: 'Kaszuby / Bory Tucholskie', bory: true, province: 'pomorskie / kujawsko-pomorskie', duration: '7 dni kajakiem', tripKind: 'multi', character: 'Wdzydze i długa leśna wyprawa', description: 'Przez jeziora Wdzydzkie, Borsk, Wojtal i Czarną Wodę do Tlenia. Wymagania zmieniają się między płyciznami, bystrymi fragmentami i otwartymi jeziorami.', hazards: 'Płycizny górnej Wdy, kamienisty fragment za Górskimi Mostami, drzewa i wiatr na jeziorach.', portages: '4 według oferty eKajaki; szczegóły zależą od miejsca startu i wyboru Wdy albo kanału.', sup: 'Hydrostacja odradza SUP na górnym odcinku z powodu płycizn. Całość wymaga dobrania etapów, sprzętu i ewentualnego późniejszego startu.', accessNote: 'Katalog zachowuje trasę kajakową. Dla SUP szczególnie istotne są opisane przez Hydrostację ograniczenia górnej Wdy.' });
add({ id: 'wierzyca-wielki-podles-gniew', river: 'Wierzyca', from: 'Wielki Podleś', to: 'Gniew', km: 142, grade: 'Średni', level: 'advanced', logs: 'many', source: multi('wierzyca_nurty_natury_nurty_kultury'), sources: [hydro], region: 'Kaszuby / Kociewie', duration: '8 dni kajakiem', tripKind: 'multi', character: 'Meandry, młyny i zabytki Kociewia', description: 'Z okolic Kościerzyny przez Starą Kiszewę, Starogard Gdański i Pelplin do Gniewu. Pozornie spokojna rzeka ma szybkie zakręty i drzewa w nurcie.', hazards: 'Pnie, głazy, bystrza i budowle hydrotechniczne.', portages: '13 według karty oferty.' });
add({ id: 'pokrzywna-glewnik-darlowko', river: 'Pokrzywna + Wieprza', from: 'Glewnik', to: 'Darłówko', km: 106, grade: 'Średni', level: 'moderate', logs: 'some', source: multi('wieprza_z_pokrzywna'), region: 'Pomorze / Pojezierze Bytowskie', province: 'pomorskie / zachodniopomorskie', duration: '6 dni kajakiem', tripKind: 'multi', character: 'Kameralna wyprawa do wybrzeża', description: 'Pokrzywną na Wieprzę, dalej przez Kępice i Sławno do Darłówka. Górne fragmenty są bardziej dynamiczne, a niżej rzeka szeroka i spokojniejsza.', hazards: 'Bystrza i pnie na górnych fragmentach; niżej infrastruktura i ruch w rejonie portowym.', portages: '6 według karty oferty.' });
add({ id: 'slupia-galaznia-ustka', river: 'Słupia', from: 'Gałąźnia Mała', to: 'Ustka', km: 74, grade: 'Średni', level: 'moderate', logs: 'some', type: 'mixed', source: multi('slupia_do_morza_w_4_dni'), region: 'Dolina Słupi / Pomorze', duration: '4 dni kajakiem', tripKind: 'multi', character: 'Dolna Słupia do Ustki', description: 'Wariant rozpoczynający się poniżej odcinków wymagających przewózek. Przez Konradowo, Krzynię i Słupsk do Ustki.', hazards: 'Jeziora zaporowe, naturalne przeszkody i miejscami wartki nurt.', portages: '3 według karty oferty.' });
add({ id: 'zbrzyca-kaszuba-mylof', river: 'Zbrzyca + Brda', rivers: ['Zbrzyca', 'Brda'], from: 'Kaszuba', to: 'Mylof', km: 46, grade: 'Łatwy', level: 'moderate', logs: 'unknown', type: 'mixed', source: multi('zbrzyca_i_brda_splyw_rodzinny'), region: 'Kaszuby / Bory Tucholskie', bory: true, duration: '4 dni kajakiem', tripKind: 'multi', character: 'Leśne jeziora i dwa szlaki', description: 'Z dolnej Zbrzycy na Brdę, przez łańcuch jezior w kierunku Mylofu. Wariant spokojnej, kilkudniowej wyprawy z zapleczem biwakowym.', hazards: 'Źródło nie opisuje zwałek; na jeziorach znaczenie mają wiatr i dystans.', portages: 'Karta oferty podaje 1, choć tekst promocyjny mówi o braku. Wymaga doprecyzowania miejsca startu i mety.', lengthNote: '46 km według karty konkretnej oferty. Opis ma rozbieżność dotyczącą przenosek; zachowano ją w szczegółach.' });

// Additional regional waterways, sourced from the regional route guide.
add({ id: 'radunia-ostrzyce-kielpino', river: 'Radunia', from: 'Ostrzyce', to: 'Kiełpino', km: 14, grade: 'Łatwy kajakowo', level: 'moderate', logs: 'some', type: 'mixed', source: ps('radunia-ostrzyce-tratkownica'), character: 'Dolina Raduni przed Jarem', description: 'Przez jezioro Trzebno, Goręczyno i Somonino do okolic Trątkownicy / Kiełpina. Łagodniejsze fragmenty przeplatają się z lokalnymi bystrzami.', current: 'Zmienny; szybszy pod mostami', hazards: 'Pale, kamienie, płycizny i pojedyncze drzewa.', portages: 'Jaz przy Ostrzycach i pozostałości progu przy Trzebnie, zależnie od miejsca startu.', accessNote: 'Trasa kończy się przed rezerwatem Jar Raduni, który jest wyłączony ze spływów.' });
add({ id: 'radunia-rutki-zukowo', river: 'Radunia', from: 'Rutki', to: 'Żukowo', km: 3, grade: 'Średnio trudny', level: 'advanced', logs: 'many', source: ps('radunia-rutki-lapino'), character: 'Krótko, ale z przeszkodami', description: 'Od elektrowni w Rutkach do przystani w Żukowie. Mimo krótkiego dystansu źródło przeznacza odcinek dla doświadczonych kajakarzy.', current: 'Początkowo spokojny, dalej wartki', hazards: 'Częste powalone drzewa i krzewy.', portages: 'Opis nie podaje liczby; miejsce startu poniżej elektrowni.', lengthNote: '3 km w treści opisu Rutki–Żukowo. Adres strony zawiera „Łapino”, lecz nie używamy go jako nazwy mety.' });
add({ id: 'radunia-straszyn-krepiec', river: 'Radunia + Motława', from: 'Straszyn', to: 'Krępiec', km: 20, grade: 'Średni', level: 'moderate', logs: 'some', source: ps('radunia-ew_straszyn-krepiec'), region: 'Okolice Gdańska / Żuławy', character: 'Szlak elektrowni wodnych', description: 'Dolna Radunia przez Prędzieszyn, Kuźnice, Juszkowo i Pruszcz Gdański do Motławy. Finał to około kilometr pod słaby prąd do Krępca.', current: 'Przeważnie łagodny', hazards: 'Urządzenia piętrzące, próg przy dawnej cukrowni i pojedyncze drzewa.', portages: 'Elektrownie Prędzieszyn, Kuźnice, Juszkowo i Pruszcz oraz próg przy cukrowni.', lengthNote: '19 km Radunią + 1 km Motławą do Krępca.', accessNote: 'Szlak prowadzi starym korytem Raduni, nie Kanałem Raduni do centrum Gdańska.' });
add({ id: 'kolko-radunskie-stezyca-golubie', river: 'Kółko Jezior Raduńskich', rivers: ['Radunia'], from: 'Stężyca', to: 'Gołubie', km: 37, grade: 'Łatwy przy spokojnej pogodzie', level: 'moderate', logs: 'low', type: 'mixed', source: ps('kolko_jezior_radunskich-stezyca-golubie'), duration: '2 dni kajakiem', tripKind: 'multi', character: 'Naszyjnik kaszubskich jezior', description: 'Przez jeziora Raduńskie, Chmielno, Brodno i Ostrzyckie, dalej Patulskie w kierunku Gołubia. To wariant do Gołubia, nie zamknięta pętla z powrotem do Stężycy.', current: 'Głównie woda stojąca', hazards: 'Wiatr i fale; płytkie, zarośnięte łączniki i niskie mostki.', portages: 'M.in. Chmielonko, połączenie w kierunku Ostrzyckiego i młyn w Gołubiu.', lengthNote: '37 km do Gołubia; źródło opisuje dodatkowe 4,2 km w kierunku Lubowiska.', schematic: true, places: ['Stężyca', 'Chmielno', 'Ręboszewo', 'Ostrzyce', 'Krzeszna', 'Gołubie'] });
add({ id: 'reda-reda-mrzezino', river: 'Reda', from: 'Reda', to: 'Mrzezino', km: 9, grade: 'Łatwy, lecz z trudnym obejściem jazu', level: 'moderate', logs: 'low', source: ps('reda-reda-mrzezino'), region: 'Kaszuby Północne', character: 'Dolna Reda przed Beką', description: 'Od parku miejskiego w Redzie przez otwartą dolinę w kierunku Mrzezina. Początek wymaga obejścia hodowli ryb i jazu.', current: 'Miejscami wartki', hazards: 'Jaz, stroma skarpa przy wodowaniu i silny wypływ z hodowli.', portages: 'Jaz hodowli pstrąga; źródło zaleca przewózkę.', accessNote: 'Zakończ przed rezerwatem Beka. Wpłynięcie do strefy ochrony ścisłej jest zabronione.' });
add({ id: 'chelst-stilo-leba', river: 'Chełst', from: 'Stilo', to: 'Łeba', km: 14.9, grade: 'Łatwy', level: 'moderate', logs: 'unknown', type: 'mixed', source: ps('kanal_chelst-stilo-leba'), region: 'Kaszuby Północne', duration: '1 dzień', tripKind: 'day', character: 'Chełst i jezioro Sarbsko', description: 'Nadmorski szlak przez jezioro Sarbsko do miasta Łeba. Rzeka uchodzi do Łeby już w miejscowości.', hazards: 'Źródło nie określa ilości zwałek; istotna otwarta powierzchnia jeziora.', portages: '2 według źródła.' });
add({ id: 'kanal-wdy-borsk-cegielnia', river: 'Kanał Wdy', rivers: ['Kanał Wdy'], from: 'Górskie Mosty', to: 'Cegielnia', km: 22.5, grade: 'Łatwy', level: 'moderate', logs: 'some', source: ps('kanal_wdy-borsk-cegielnia'), region: 'Kaszuby / Bory Tucholskie', bory: true, duration: '1 dzień', tripKind: 'day', character: 'Leśny kanał i zastawki', description: 'Alternatywa dla głównego koryta Wdy od rozdzielenia rzeki i kanału poniżej Borska. Po drodze Bąk, odcinki leśne oraz urządzenia nawadniające.', current: 'Słaby; źródło dopuszcza pływanie w obie strony', hazards: 'Powalone i pochylone drzewa, niskie przepusty i zastawki.', portages: 'Obejścia zastawek; opis nie podaje stałej liczby.', lengthNote: 'Tabela podaje 22,5 km; wstęp wspomina 18 km, a opis przekracza 20 km. Zachowano wartość tabeli z zaznaczeniem rozbieżności.' });
add({ id: 'mlosina-lesno-kaszuba', river: 'Młosina + Zbrzyca', rivers: ['Młosina', 'Zbrzyca'], from: 'Leśno', to: 'Kaszuba', km: 4, grade: 'Łatwy', level: 'easy', logs: 'low', source: ps('mlosina-lesno-kaszuba'), region: 'Kaszuby / Zaborski Park Krajobrazowy', bory: true, character: 'Krótki dopływ Zbrzycy', description: 'Od Leśna doliną Młosiny do połączenia ze Zbrzycą, potem do przystani w Kaszubie. Łąki przechodzą w krajobraz leśny.', hazards: 'Niski mostek; źródło opisuje szlak jako nieuciążliwy.', portages: 'Opis nie wymienia stałych przenosek.', lengthNote: '3 km Młosiną + 1 km Zbrzycą do Kaszuby.' });
add({ id: 'niechwaszcz-chlopowy-czarna-woda', river: 'Niechwaszcz + Wda', rivers: ['Niechwaszcz', 'Wda'], from: 'Chłopowy', to: 'Czarna Woda', km: 28, grade: 'Górny fragment łatwy, dolny średni i techniczny', level: 'advanced', logs: 'many', source: ps('niechwaszcz-debowiec-czarna_woda'), sources: [hydroGuide], region: 'Kaszuby / Bory Tucholskie', bory: true, character: 'Od łąk do bobrowych zwałek', description: 'Cały opisany szlak z Chłopowych przez Dębowiec, Mniszek i Zawadę do Wdy. Górny fragment jest uregulowany, dolny wąski, leśny i szybki.', current: 'Szybszy w dolnym biegu', hazards: 'Zwałki bobrowe, głazy i bystrza przed ujściem.', portages: 'Zastawka koło Mniszka i jaz w Zawadzie; dodatkowo naturalne przeszkody.', lengthNote: '28 km z opisu całego szlaku. Strony zatytułowane jako części trasy powtarzają pełny kilometraż; nie przypisujemy 28 km każdej części.' });
add({ id: 'graniczna-wieprznica-rybaki', river: 'Graniczna', from: 'Wieprznica', to: 'Rybaki', km: 8.4, grade: 'Łatwy kajakowo', level: 'moderate', logs: 'some', type: 'mixed', source: ps('graniczna-wieprznica-rybaki'), character: 'Mała rzeka i jeziora pod Kościerzyną', description: 'Przez jeziora Wieprznickie, Garczyn i Graniczne w stronę Sudomia. Wąskie rzeczne łączniki przeplatają się z jeziorami.', hazards: 'Płycizny, zastawka i wąskie przepusty pod torami oraz drogą.', portages: 'Przy zastawce i problematycznym przepuście za Garczynem; sposób obejścia trzeba ustalić na miejscu.' });
add({ id: 'pilica-kaszubska-korne-lubiana', river: 'Pilica kaszubska', rivers: ['Pilica rzeka, pomorskie', 'Borowa rzeka, pomorskie'], from: 'Korne', to: 'Łubiana', km: 7, grade: 'Łatwy kajakowo', level: 'moderate', logs: 'some', source: ps('pilica-korne-lubiana'), character: 'Wąski, kręty kaszubski dopływ', description: 'Start przy dawnym młynie w Kornem, krótką Borową do Pilicy i dalej koło Łubiany. To inna Pilica niż duża rzeka w centralnej Polsce.', hazards: 'Płycizny, zniszczony jaz, niski mostek, kamienie i kilka drzew.', portages: 'Możliwe przy jazie i płyciznach; brak podanej liczby.' });
add({ id: 'trzebiocha-rybaki-loryniec', river: 'Trzebiocha + Wda', from: 'Rybaki', to: 'Loryniec', km: 8.1, grade: 'Łatwy kajakowo, z szybką końcówką', level: 'moderate', logs: 'some', type: 'mixed', source: ps('trzebiocha-rybaki-loryniec'), character: 'Jeziora i Grzybowski Młyn', description: 'Od Sudomia w kierunku Grzybowskiego Młyna, następnie do ujścia do Wdy i przystani w Loryńcu. Za młynem nurt przyspiesza.', current: 'Wartki za Grzybowskim Młynem', hazards: 'Płycizny, wodorosty, drzewa i żwirowo-kamieniste bystrza.', portages: 'Przy pozostałościach jazu oraz przy hodowli w Grzybowskim Młynie; obejście ogrodzenia.', lengthNote: '7,6 km Trzebiochą + 0,5 km Wdą do Loryńca.' });
add({ id: 'wietcisa-wolny-dwor-czarnocin', river: 'Wietcisa', from: 'Wolny Dwór', to: 'Czarnocin', km: 12, grade: 'Trudny', level: 'advanced', logs: 'many', source: ps('wietcisa-wolny_dwor-czarnocin'), region: 'Kaszuby / Kociewie', duration: '1 dzień', tripKind: 'day', character: 'Szybki leśny przełom', description: 'Krótki techniczny szlak przez Skarszewy. Końcowy fragment prowadzi malowniczym leśnym przełomem.', current: 'Szybki', hazards: 'Liczne bystrza, płycizny i zwałki.', portages: 'Skarszewy i Dolina Młyn.' });
